@app.route('/login', methods=['GET', 'POST'])
def login():
    # --------------------------------------------
    if request.method == 'GET':
        # --------------------------------------------
        username = request.args.get('username', '')
        password = request.args.get('password', '')
    else:
        username = request.form.get('username', '')
        password = request.form.get('password', '')

    if not username or not password:
        return render_template_string('''
            <h2>Login</h2>
            <form method="POST">
                Username: <input name="username"><br>
                Password: <input type="password" name="password"><br>
                <input type="submit" value="Login">
            </form>
        ''')

    try:
        conn = sqlite3.connect('vulnerable_app.db')
        cursor = conn.cursor()

        # --------------------------------------------
        query = f"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'"
        cursor.execute(query)
        user = cursor.fetchone()
        conn.close()

        if user:
            session['username'] = user[1]
            session['role'] = user[4]
            return f"<h2>Login successful! Welcome {user[1]}</h2><br><a href='/profile'>View Profile</a>"
        else:
            # --------------------------------------------
            return f"<h2>Login failed for user: {username}</h2><p>Invalid credentials provided</p>"

    except Exception as e:
        # --------------------------------------------
        import logging
        logging.error(f"Database error during login: {e}")
        return "<h2>Error</h2><p>An internal error occurred. Please try again later.</p>"
